// Dumps the game's IL2CPP interop assemblies (generated by BepInEx) to grep-able text:
// one block per type with its base type, fields, properties and methods.
// Usage: dotnet run -- <BepInEx dir> <out dir> [assembly names...]
using System.Reflection;
using System.Runtime.Loader;
using System.Text;

var bepinex = args.Length > 0 ? args[0] : throw new ArgumentException("BepInEx dir required");
var outDir = args.Length > 1 ? args[1] : ".";
var names = args.Length > 2 ? args[2..] : new[] { "Assembly-CSharp", "Assembly-CSharp-firstpass" };
var searchDirs = new[] { Path.Combine(bepinex, "interop"), Path.Combine(bepinex, "core") };

var alc = new AssemblyLoadContext("dump", isCollectible: false);
alc.Resolving += (ctx, name) =>
{
    foreach (var dir in searchDirs)
    {
        var p = Path.Combine(dir, name.Name + ".dll");
        if (File.Exists(p)) return ctx.LoadFromAssemblyPath(p);
    }
    return null;
};

const BindingFlags All = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance |
                         BindingFlags.Static | BindingFlags.DeclaredOnly;
Directory.CreateDirectory(outDir);
foreach (var asmName in names)
{
    var asm = alc.LoadFromAssemblyPath(Path.Combine(searchDirs[0], asmName + ".dll"));
    Type[] types;
    try { types = asm.GetTypes(); }
    catch (ReflectionTypeLoadException e) { types = e.Types.Where(t => t != null).ToArray()!; }

    var sb = new StringBuilder();
    foreach (var t in types.OrderBy(t => t.FullName))
    {
        if (t.Name.StartsWith("<") || t.Name.Contains("NativeMethodInfoPtr")) continue;
        string baseName;
        try { baseName = t.BaseType?.FullName ?? "-"; } catch { baseName = "?"; }
        sb.AppendLine($"type {t.FullName} : {baseName}");
        try
        {
            foreach (var f in t.GetFields(All))
            {
                if (f.Name.StartsWith("NativeFieldInfoPtr_") || f.Name.StartsWith("NativeMethodInfoPtr_")) continue;
                sb.AppendLine($"  field {(f.IsStatic ? "static " : "")}{Safe(() => f.FieldType.Name)} {f.Name}");
            }
            foreach (var p in t.GetProperties(All))
                sb.AppendLine($"  prop {(p.GetMethod?.IsStatic == true ? "static " : "")}{Safe(() => p.PropertyType.Name)} {p.Name}");
            foreach (var m in t.GetMethods(All))
            {
                if (m.IsSpecialName && (m.Name.StartsWith("get_") || m.Name.StartsWith("set_"))) continue;
                var ps = Safe(() => string.Join(", ", m.GetParameters().Select(x => x.ParameterType.Name + " " + x.Name)));
                sb.AppendLine($"  method {(m.IsStatic ? "static " : "")}{Safe(() => m.ReturnType.Name)} {m.Name}({ps})");
            }
        }
        catch (Exception e) { sb.AppendLine("  !! " + e.GetType().Name + ": " + e.Message); }
    }
    var outPath = Path.Combine(outDir, asmName + ".txt");
    File.WriteAllText(outPath, sb.ToString());
    Console.WriteLine($"{asmName}: {types.Length} types -> {outPath}");
}

static string Safe(Func<string> f) { try { return f(); } catch { return "?"; } }
